const t=new Date().toISOString().slice(0,10);
const orders=$('Read orders (recon)').all().map(i=>i.json).filter(r=>(r.Date||'').startsWith(t)&&r.Payment!=='COD');
const oSum=orders.reduce((s,r)=>s+(Number(String(r.Amount).replace(/[^0-9.]/g,''))||0),0);
const pays=($json.items||[]).filter(p=>p.status==='captured');
const pSum=pays.reduce((s,p)=>s+p.amount/100,0);
const diff=Math.round(oSum-pSum);
return [{ json: { text: Math.abs(diff)<=1 ? `✅ Reconciliation OK: orders ₹${oSum.toLocaleString('en-IN')} = captured ₹${pSum.toLocaleString('en-IN')}` : `🔴 RECON MISMATCH today: orders(prepaid) ₹${oSum.toLocaleString('en-IN')} vs captured ₹${pSum.toLocaleString('en-IN')} (diff ₹${diff.toLocaleString('en-IN')}) — check pending/failed payments & manual bills.` } }];
